-- The CUT-GRIP code key (Code keys -> Parting -> CUT-GRIP), from the ISCAR
-- e-catalog's CUT-GRIP families (precision and utility inserts, GIM, and their
-- tools, blades and adapters); kept if one exists. "(inferred)" marks meanings
-- read off the designations.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.cutgrip', $ck${"title": "CUT-GRIP code key – inserts and tools", "subtitle": "Precision (ground) and utility grooving, turning and parting inserts, and their tools, blades and adapters", "example": "GIP 3.00E-0.40", "decoder": "cut-grip", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "GIP", "rows": [{"code": "GIP", "meaning": "Precision double-ended inserts for grooving (external)"}, {"code": "GIPI", "meaning": "Precision double-ended inserts for internal grooving and recessing"}, {"code": "GIPA", "meaning": "Precision ground inserts with a polished top rake for aluminum"}, {"code": "GIPY", "meaning": "Single-ended full radius sharp edged precision inserts for profiling high temperature alloys"}, {"code": "GIPM", "meaning": "Precision ground back turning inserts for Swiss-type and automatic machines"}, {"code": "GIF", "meaning": "Precision double-ended inserts for grooving"}, {"code": "GIFI", "meaning": "Precision double-ended inserts for internal grooving"}, {"code": "GIFG", "meaning": "Inserts for deep face grooving and turning"}, {"code": "GIG", "meaning": "Precision double-ended inserts for grooving"}, {"code": "GEPI", "meaning": "Precision ground double-ended inserts for internal and external grooving"}, {"code": "GIA", "meaning": "Flat top precision double-ended inserts with T-land for cast iron"}, {"code": "GITM", "meaning": "CBN tipped inserts for turning and grooving hard ferrous materials"}, {"code": "GINI", "meaning": "Precision double-ended inserts for internal grooving and turning of ductile materials"}, {"code": "GIDA", "meaning": "Precision double-ended inserts with polished top rake for aluminum (sizes x10)"}, {"code": "GDMU", "meaning": "Utility inserts for heavy grooving on ductile materials"}, {"code": "GDMW", "meaning": "Utility double-ended inserts for external turning, grooving and parting"}, {"code": "GDMY", "meaning": "Utility double-ended inserts for grooving and turning"}, {"code": "GDMF", "meaning": "Utility double-ended inserts for grooving and turning"}, {"code": "GDMA", "meaning": "Utility double-ended insert for aluminum"}, {"code": "GDMN", "meaning": "Utility double-ended inserts for grooving and turning ductile materials"}, {"code": "GDMT", "meaning": "Utility double-ended inserts for grooving and turning"}, {"code": "GDMM", "meaning": "Single-ended utility insert for rough grooving and side turning with a front chip splitter"}, {"code": "GIMY", "meaning": "Utility single-ended inserts for grooving and turning"}, {"code": "GIMIY", "meaning": "Utility single-ended inserts for internal grooving and turning"}, {"code": "GIMF", "meaning": "Utility single-ended inserts for grooving and turning"}, {"code": "GIMN", "meaning": "Utility single-ended inserts for grooving and turning ductile materials"}, {"code": "GIMT", "meaning": "Utility single-ended inserts for grooving and turning"}, {"code": "GIMM", "meaning": "Single-ended utility insert with a front chip splitter for rough grooving and side turning"}, {"code": "GEMI", "meaning": "Utility double-ended inserts for internal and external grooving and turning (width and radius x10)"}, {"code": "GIM", "meaning": "Utility single-sided inserts for parting and grooving"}]}, {"key": "i-width", "title": "Insert – cutting width (and corner radius)", "sample": "3.00", "rows": [{"code": "#", "meaning": "Precision: cutting width in mm (e.g. 3.00). Utility: width and corner radius x10 (e.g. 808 = 8 mm, R0.8)"}]}, {"key": "i-type", "title": "Insert – type", "sample": "E", "rows": [{"code": "E", "meaning": "For grooving and turning (e.g. GIP-E vs GIP for grooving)"}, {"code": "K", "meaning": "T-land / hard ferrous (GIA-K for cast iron, GITM CBN tipped) (inferred)"}]}, {"key": "i-radius", "title": "Insert – corner radius", "sample": "0.40", "rows": [{"code": "#", "meaning": "Corner radius in mm (e.g. 0.40); half the width = full radius"}]}, {"key": "i-variant", "title": "Insert – variant", "rows": [{"code": "UN", "meaning": "Undercutting, neutral"}, {"code": "UR", "meaning": "Undercutting, right"}, {"code": "UL", "meaning": "Undercutting, left"}, {"code": "RX", "meaning": "Next to a shoulder, right"}, {"code": "LX", "meaning": "Next to a shoulder, left"}, {"code": "F", "meaning": "Grooving and profiling ductile materials (e.g. GIMY 840F)"}, {"code": "CC", "meaning": "Front chip splitter (rough grooving and side turning)"}, {"code": "YZ", "meaning": "YZ variant (aluminum inserts) (inferred)"}, {"code": "CB", "meaning": "CB variant (inferred)"}, {"code": "D", "meaning": "D variant (e.g. GIPA 3.00-0.20-D) (inferred)"}, {"code": "N", "meaning": "N variant (e.g. GEMI 2002N) (inferred)"}, {"code": "M", "meaning": "M variant (e.g. GEMI 3002M) (inferred)"}, {"code": "Y", "meaning": "Y variant, full radius (e.g. GEMI 2010Y) (inferred)"}, {"code": "L", "meaning": "Left-hand version (e.g. GIP 3.00-1250L) (inferred)"}, {"code": "R", "meaning": "Right-hand version (inferred)"}]}, {"key": "i-chip", "title": "GIM – chipformer", "rows": [{"code": "J", "meaning": "Soft materials, tubes and small diameters"}, {"code": "C", "meaning": "Bars, hard materials and tough applications"}, {"code": "W", "meaning": "Central ridged chipformer and reinforced edge"}, {"code": "UT", "meaning": "Low feeds on CrNi alloys"}]}, {"key": "i-sharp", "title": "GIM – sharp corners", "rows": [{"code": "S", "meaning": "Sharp corners"}]}, {"key": "i-lead", "title": "GIM – lead angle and hand", "rows": [{"code": "#RA", "meaning": "Lead angle (°), right-hand"}, {"code": "#LA", "meaning": "Lead angle (°), left-hand"}, {"code": "##RA", "meaning": "Lead angle (°), right-hand"}, {"code": "##LA", "meaning": "Lead angle (°), left-hand"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "GHD", "meaning": "External tools for turning, grooving and parting (GHDR/L short / long pocket, -JHP, -JHP-MC, 12/14 wide)"}, {"code": "GHG", "meaning": "External holders for deep grooving and parting"}, {"code": "GHS", "meaning": "External grooving and turning holders for Swiss-type and automatic machines"}, {"code": "GEHS", "meaning": "External machining holders for Swiss-type and automatic machines"}, {"code": "GHM", "meaning": "Toolholders for shallow radial and axial grooving with narrow and special profile inserts"}, {"code": "GHMP", "meaning": "Perpendicular toolholders for shallow radial and axial grooving"}, {"code": "GHFG", "meaning": "Holders for face grooving and turning (along shafts)"}, {"code": "PHG", "meaning": "Holders for external grooving and turning (GDMW inserts)"}, {"code": "PHS", "meaning": "External machining holders for Swiss-type machines (GDMW inserts)"}, {"code": "CGH", "meaning": "Blades for grooving and turning (CGHN-D double-ended, -S single-ended, -P8 deep, CGHR/L-P8DG, -12-14D)"}, {"code": "CGFG", "meaning": "Blades for face machining carrying 8 mm inserts"}, {"code": "GAD", "meaning": "Adapters for up to 25 mm deep machining (GADR/L-8, -JHP)"}, {"code": "GAFG", "meaning": "Adapters for face machining"}, {"code": "PAD", "meaning": "Adapters for GDMW / GDMY inserts"}, {"code": "THD", "meaning": "External holders for wide (20 mm) grooving inserts"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}, {"code": "R/L", "meaning": "Right- or left-hand"}, {"code": "N", "meaning": "Neutral"}, {"code": "RE", "meaning": "Right-hand, E type (RE/LE adapters) (inferred)"}, {"code": "LE", "meaning": "Left-hand, E type (RE/LE adapters) (inferred)"}, {"code": "R/LE", "meaning": "Right- or left-hand, E type (inferred)"}]}, {"key": "t-angle", "title": "Tool – angle a° (multi-spindle blades)", "rows": [{"code": "#", "meaning": "Angle a° (0 or 5)"}]}, {"key": "t-height", "title": "Tool – blade height / shank", "rows": [{"code": "##", "meaning": "Blade height or shank size in mm (e.g. 26, 32)"}, {"code": "###", "meaning": "Blade height in mm (e.g. 100, 150)"}, {"code": "####", "meaning": "Shank height x width in mm (e.g. 2525 = 25 x 25)"}]}, {"key": "t-width", "title": "Tool – insert width (seat)", "rows": [{"code": "#", "meaning": "Insert width in mm (the seat's insert, e.g. 3)"}]}, {"key": "t-dia", "title": "Tool – D size", "rows": [{"code": "D##", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D24, D52) (inferred)"}, {"code": "D###", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D120) (inferred)"}]}, {"key": "t-pockets", "title": "Tool – pockets", "rows": [{"code": "#Z", "meaning": "Number of pockets (e.g. 2Z, 4Z)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "JHP", "meaning": "Channels for high-pressure coolant"}, {"code": "MC", "meaning": "Bottom inlets for the high-pressure coolant"}, {"code": "K", "meaning": "With coolant holes (10 bar min.; cooling tube SGCU 341 ordered separately)"}, {"code": "C", "meaning": "With coolant – frontal coolant holes (JETCUT) / internal coolant"}, {"code": "XL", "meaning": "Extra long"}, {"code": "SH", "meaning": "Short head (CNC and Swiss automatics)"}, {"code": "S", "meaning": "Single-sided blade (e.g. TGFH-S) / for next to high shoulders (e.g. PCHRS)"}, {"code": "IQ", "meaning": "IQ line (e.g. TGTR/L-IQ, PCHR/L-D-IQ)"}, {"code": "TR", "meaning": "For TRAUB and Index machines"}, {"code": "MB", "meaning": "For other manufacturers' blocks"}, {"code": "B", "meaning": "B type, e.g. DGTR/L-B-D (reinforced) / DGAD-B-D (screw-clamped) (inferred)"}, {"code": "L###", "meaning": "Tool length in mm (e.g. L120)"}, {"code": "ST", "meaning": "ST version (e.g. GHDR 16-3 ST) (inferred)"}, {"code": "D", "meaning": "Double-ended blade (e.g. CGHN 32-3D)"}, {"code": "DG", "meaning": "Double-ended blade for self-clamped inserts (CGHN-DG)"}, {"code": "P8", "meaning": "For 8 mm (P8) inserts – deep grooving (inferred)"}, {"code": "P8DG", "meaning": "Double-ended heavy duty self-clamped blade for 8 mm inserts"}, {"code": "SL", "meaning": "Side lock clamping"}, {"code": "T##", "meaning": "T size (e.g. 14T12, 20T38) (inferred)"}, {"code": "###", "meaning": "Pocket / insert variant (e.g. GHDR 32-812) – see the catalog"}, {"code": "C#", "meaning": "CAMFIX polygon shank (C4 = 40, C5 = 50, C6 = 63 mm)"}]}, {"key": "t-dmin", "title": "Tool – face grooving diameter", "rows": [{"code": "##", "meaning": "Minimum face grooving diameter in mm (inferred)"}, {"code": "###", "meaning": "Minimum face grooving diameter in mm (inferred)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
